BEGIN;
SELECT plan(26);
INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data) VALUES
 ('00000000-0000-0000-0000-0000000fe101','launch-admin@t.local','{"name":"Admin"}','{}'),
 ('00000000-0000-0000-0000-0000000fe102','launch-manager@t.local','{}','{"account_type":"staff"}');
SELECT app_private.bootstrap_admin('launch-admin@t.local'); -- first administrator (no longer the first sign-up)
UPDATE public.users SET active=true;
UPDATE public.users SET role='manager' WHERE id='00000000-0000-0000-0000-0000000fe102';
SET LOCAL ROLE authenticated;
SET LOCAL "request.jwt.claims"='{"sub":"00000000-0000-0000-0000-0000000fe101","role":"authenticated","aal":"aal2"}';
SELECT is((update_settings('{"online_max_pending_orders":5,"online_max_open_cod_orders":6}')->>'online_max_pending_orders')::int,5,'admin sets pending limit');
SELECT is((SELECT online_max_open_cod_orders FROM app_settings),6,'admin sets COD limit');
SELECT throws_ok($$SELECT update_settings('{"online_max_pending_orders":0}')$$,'P0001',NULL,'zero pending refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_pending_orders":51}')$$,'P0001',NULL,'51 pending refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_open_cod_orders":0}')$$,'P0001',NULL,'zero COD refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_open_cod_orders":51}')$$,'P0001',NULL,'51 COD refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_open_cod_orders":1.5}')$$,'P0001',NULL,'fraction refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_pending_orders":null}')$$,'P0001',NULL,'null refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_pending_orders":"3"}')$$,'P0001',NULL,'text refused');
CREATE TEMP TABLE launch_style(id uuid);GRANT ALL ON launch_style TO authenticated;
INSERT INTO launch_style SELECT save_style('{"code":"LAUNCH-COMPARE","name":"Launch helmet","kind":"item","variants":[{"sku":"LAUNCH-COMPARE","size":"M","price":1000,"compare_at_price":1500}]}');
SELECT is((SELECT compare_at_price FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),1500::numeric,'compare-at saved');
SELECT save_style(jsonb_build_object('style_id',(SELECT id FROM launch_style),'code','LAUNCH-COMPARE','name','Launch helmet','kind','item','variants',jsonb_build_array(jsonb_build_object('variant_id',(SELECT id FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),'sku','LAUNCH-COMPARE','size','M','price',1000,'compare_at_price',1600))));
SELECT is((SELECT compare_at_price FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),1600::numeric,'compare-at updated');
SELECT save_style(jsonb_build_object('style_id',(SELECT id FROM launch_style),'code','LAUNCH-COMPARE','name','Launch helmet','kind','item','variants',jsonb_build_array(jsonb_build_object('variant_id',(SELECT id FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),'sku','LAUNCH-COMPARE','size','M','price',1000))));
SELECT is((SELECT compare_at_price FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),1600::numeric,'omitted compare-at preserved');
SELECT save_style(jsonb_build_object('style_id',(SELECT id FROM launch_style),'code','LAUNCH-COMPARE','name','Launch helmet','kind','item','variants',jsonb_build_array(jsonb_build_object('variant_id',(SELECT id FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),'sku','LAUNCH-COMPARE','size','M','price',1000,'compare_at_price',null))));
SELECT is((SELECT compare_at_price FROM product_variants WHERE style_id=(SELECT id FROM launch_style)),null::numeric,'explicit null clears compare-at');
SELECT is((SELECT published FROM product_styles WHERE id=(SELECT id FROM launch_style)),false,'new style stays unpublished');
SELECT is((SELECT count(*)::int FROM variant_costs WHERE variant_id IN(SELECT id FROM product_variants WHERE style_id=(SELECT id FROM launch_style))),0,'no cost created');
SELECT is((SELECT count(*)::int FROM stock_movements WHERE variant_id IN(SELECT id FROM product_variants WHERE style_id=(SELECT id FROM launch_style))),0,'no stock movement created');
SELECT throws_ok($$SELECT save_style('{"code":"NEGATIVE-COMPARE","name":"Bad","variants":[{"sku":"NEGATIVE-COMPARE","price":1,"compare_at_price":-1}]}')$$,'P0001',NULL,'negative compare-at refused');
SELECT throws_ok($$SELECT save_style('{"code":"FRACTION-COMPARE","name":"Bad","variants":[{"sku":"FRACTION-COMPARE","price":1,"compare_at_price":1.111}]}')$$,'P0001',NULL,'excess precision refused');
SELECT throws_ok($$SELECT save_style('{"code":"NAN-COMPARE","name":"Bad","variants":[{"sku":"NAN-COMPARE","price":1,"compare_at_price":"NaN"}]}')$$,'P0001',NULL,'nonfinite compare-at refused');
SELECT throws_ok($$SELECT save_style('{"code":"INF-COMPARE","name":"Bad","variants":[{"sku":"INF-COMPARE","price":1,"compare_at_price":"Infinity"}]}')$$,'P0001',NULL,'infinite compare-at refused');
SELECT throws_ok($$SELECT save_style('{"code":"HUGE-COMPARE","name":"Bad","variants":[{"sku":"HUGE-COMPARE","price":1,"compare_at_price":1000000000000}]}')$$,'P0001',NULL,'oversized compare-at refused');
SET LOCAL "request.jwt.claims"='{"sub":"00000000-0000-0000-0000-0000000fe102","role":"authenticated","aal":"aal2"}';
SELECT throws_ok($$SELECT update_settings('{"online_max_pending_orders":4}')$$,'42501',NULL,'manager pending refused');
SELECT throws_ok($$SELECT update_settings('{"online_max_open_cod_orders":4}')$$,'42501',NULL,'manager COD refused');
SELECT lives_ok($$INSERT INTO customers(name,phone) VALUES ('Launch Customer','0300 1234567')$$,'staff can add a customer directly (phone trigger)');
SELECT ok((SELECT phone FROM customers WHERE name='Launch Customer') !~ ' ','customer phone normalised by the trigger');
SET LOCAL ROLE anon;
SELECT is((catalog_policy()->>'return_window_days')::int,7,'public policy exposes only return window');
SELECT * FROM finish();ROLLBACK;
